          "text": "गेने, एक युवा डच मिशनरी, 1955 में कम्युनिस्ट अधिकारियों द्वारा आयोजित विश्व युवा महोत्सव के लिए वारसॉ गया, और उसने अपनी आँखों से देखा कि सोवियत खेमे के देशों में विश्वासियों को एक छोटी-सी जेब वाली बाइबल तक छिपानी पड़ती थी। घर लौटकर, उसने ख़ुद वहाँ पवित्रशास्त्र ले जाने का फ़ैसला किया, इसे एक पुरानी नीली फ़ोक्सवैगन बीटल की डिक्की में छिपाकर — शुरू से ही यह मानते हुए कि ऐसी यात्रा में असली सुरक्षा कोई चतुर छिपने की जगह नहीं, बल्कि हर ठोस सीमा पर परमेश्वर पर सीधा भरोसा है।",
