          "text": "आशा, लंदन की एक साधारण नौकरानी जिसकी कोई औपचारिक शिक्षा नहीं थी, चीन में मिशनरी बनने का सपना देखती थी, लेकिन मिशनरी सोसाइटी ने ज़रूरी प्रशिक्षण न होने की वजह से उसे मना कर दिया। जवाब में उसने बस इतनी प्रार्थना की: «प्रभु यीशु, अगर तू रास्ता खोल दे और दिखा दे कि कैसे, तो मैं ख़ुद चली जाऊँगी» — और तय किया कि जब सोसाइटी उसे भेजने को तैयार नहीं है, तो वह ख़ुद ही जाएगी, बाक़ी सब कुछ प्रार्थना पर छोड़ते हुए। 1932 में उसने अपनी मामूली बचत से ट्रांस-साइबेरियन एक्सप्रेस का टिकट ख़रीदा और अकेले, युद्ध क्षेत्र से होकर, चीन के छोटे शहर यांगचेंग पहुँची।",
