          "text": "आशा सौ से ज़्यादा बच्चों के पूरे काफ़िले को पैदल पहाड़ों के रास्ते ले गई, उनके साथ आख़िरी टुकड़े तक खाना बाँटते हुए और खुले आसमान के नीचे रातें बिताते हुए; रास्ते में एक जापानी विमान ने काफ़िले पर गोलीबारी की, और आशा घायल हो गई, लेकिन उसने यात्रा जारी रखी। जब थका-हारा समूह उफनती पीली नदी के किनारे पहुँचा और किनारे पर एक भी नाव नहीं दिखी, तो आशा ने बच्चों को अपने चारों ओर इकट्ठा किया और पार जाने के लिए ज़ोर से प्रार्थना की — और जल्द ही किनारे पर सचमुच एक चीनी अफ़सर नावों के साथ आ पहुँचा, जिसने पूरे समूह को दूसरे किनारे पहुँचाया। बारह दिनों की यात्रा के बाद थका हुआ काफ़िला सुरक्षित शहर शीआन पहुँचा — सभी बच्चे बच गए।",
          "next": "aylward_choice2"
