          "text": "मोहन ने फिर से दस्तावेज़ पर दस्तख़त करने से इनकार करने की ताक़त अपने भीतर पाई, और उसे पूछताछ के कई और महीनों के लिए कोठरी में ही रखा गया। तब जाँच अधिकारियों ने चाल बदली और उसे नहीं बल्कि उसकी पत्नी को धमकाने लगे, जो ख़ुद भी हिरासत में थी, यह चेतावनी देते हुए कि अगर मोहन ज़िद करता रहा तो जेल में उसका स्वास्थ्य ज़्यादा दिन नहीं टिकेगा। ख़ुद के लिए कहीं ज़्यादा पत्नी की चिंता से थका हुआ, वह ऐसे दबाव के कुछ और महीनों बाद आख़िर आंदोलन के प्रति वफ़ादारी की स्वीकारोक्ति पर दस्तख़त कर बैठा, और दोनों को घर भेज दिया गया।",
