          "text": "यामिनी ने एक ईसाई से शादी की, तब वह दूसरे बच्चे के गर्भ के आख़िरी महीनों में थी — लेकिन काग़ज़ों में वह औपचारिक रूप से मुस्लिम दर्ज थी, और एक ईसाई से शादी ने अदालत की नज़र में उसे एक साथ दो आरोपों में डाल दिया: धर्मत्याग और «व्यभिचार»। सभी प्रारंभिक सुनवाइयों में वह एक ही बात दोहराती रही — कि माँ ने जन्म से ही उसे ईसाई के रूप में पाला था और काग़ज़ यह नहीं बदल सकता कि वह असल में किस पर विश्वास करती है — बहुत पहले से, इससे पहले कि यह बात उसके लिए जीवन-मृत्यु का सवाल बन जाए। मई 2014 में खारतूम की अदालत ने यामिनी को सौ कोड़ों और फाँसी की सज़ा सुनाई।",
