          "text": "जय, एक फ़िलिपीनी मुक्केबाज़, जो घोर ग़रीबी से उठकर राष्ट्रीय नायक और एक साथ कई भार-वर्गों में विश्व चैंपियन बना, सालों तक जुए, शराब और पत्नी जिंकी से बेवफ़ाई से भरी ज़िंदगी जीता रहा। उसने ख़ुद बाद में क़बूल किया: «रविवार को मैं चर्च जाता था, और सोमवार से शनिवार तक बार में बैठकर पीता था»। जिंकी बहुत पहले से अकेली चर्च जाती थी और कभी-कभार बिस्तर के पास की मेज़ पर भजनों पर खुली बाइबल छोड़ जाती थी — जय हर बार इसे बंद करके बिना एक भी पंक्ति पढ़े दराज़ में रख देता था।",
